add_action( 'template_redirect', 'perfectpixel_redirect_category_pages' );

function perfectpixel_redirect_category_pages() {
	if ( ! function_exists( 'is_product_category' ) || ! is_product_category() ) {
		return;
	}
	$term = get_queried_object();
	$ids  = wp_parse_id_list( '{{category_redirect_ids}}' );
	if ( ! $term || ( $ids && ! in_array( (int) $term->term_id, $ids, true ) ) ) {
		return;
	}
	$url = str_replace( '{slug}', rawurlencode( $term->slug ), '{{category_redirect_url}}' );
	$url = 0 === strpos( $url, '/' ) ? home_url( $url ) : $url;
	wp_safe_redirect( $url, '302' === trim( '{{category_redirect_status}}' ) ? 302 : 301 );
	exit;
}
